model:
rachana: 1
sutra: design
version: 1
description: 
match: { kind: design, priority: 10 }
title: { pill: "Protein engineering · Protein design", id: "$.DESIGN_ID" }
strip:
  - { label: "Design id", bind: "$.DESIGN_ID" }
  - { label: "Round", bind: "$.ROUND", fmt: "amount0" }
  - { label: "N changes", bind: "$.N_CHANGES", fmt: "amount0" }
  - { label: "Activity", bind: "$.ACTIVITY" }
  - { label: "Status", bind: "$.STATUS", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Protein design"
    columns:
      - { label: "Design id", bind: "$.DESIGN_ID" }
      - { label: "Protein", bind: "link($.PROTEIN, 'protein')" }
      - { label: "Round", bind: "$.ROUND", fmt: "amount0" }
      - { label: "Parent", bind: "$.PARENT" }
      - { label: "N changes", bind: "$.N_CHANGES", fmt: "amount0" }
      - { label: "Changes", bind: "$.CHANGES" }
      - { label: "Activity", bind: "$.ACTIVITY" }
      - { label: "Delta tm", bind: "$.DELTA_TM" }
      - { label: "Model score", bind: "$.MODEL_SCORE" }
      - { label: "Status", bind: "$.STATUS" }
      - { label: "Emb x", bind: "$.EMB_X" }
      - { label: "Emb y", bind: "$.EMB_Y" }
keys: { F9: "raw" }
